import sys,re
# parse tmux -e capture into per-cell attribute description
def parse(line):
    out=[]
    cur={'fg':'','bg':'','a':set()}
    i=0
    while i < len(line):
        if line[i]=='\x1b':
            m=re.match(r'\x1b\[([0-9;]*)m', line[i:])
            if m:
                codes=[c for c in m.group(1).split(';')]
                if codes==['']: codes=['0']
                j=0
                while j<len(codes):
                    c=int(codes[j])
                    if c==0: cur={'fg':'','bg':'','a':set()}
                    elif c==1: cur['a'].add('bold')
                    elif c==2: cur['a'].add('dim')
                    elif c==3: cur['a'].add('ital')
                    elif c==4: cur['a'].add('undl')
                    elif c==5: cur['a'].add('blink')
                    elif c==7: cur['a'].add('inv')
                    elif c==9: cur['a'].add('strk')
                    elif c==22: cur['a'].discard('bold'); cur['a'].discard('dim')
                    elif c==23: cur['a'].discard('ital')
                    elif c==24: cur['a'].discard('undl')
                    elif c==25: cur['a'].discard('blink')
                    elif c==27: cur['a'].discard('inv')
                    elif c==29: cur['a'].discard('strk')
                    elif 30<=c<=37: cur['fg']=str(c)
                    elif c==39: cur['fg']=''
                    elif 40<=c<=47: cur['bg']=str(c)
                    elif c==49: cur['bg']=''
                    elif 90<=c<=97: cur['fg']=str(c)
                    elif 100<=c<=107: cur['bg']=str(c)
                    elif c==38 or c==48:
                        key='fg' if c==38 else 'bg'
                        if j+1<len(codes) and codes[j+1]=='5': cur[key]='256:'+codes[j+2]; j+=2
                        elif j+1<len(codes) and codes[j+1]=='2': cur[key]='rgb:'+':'.join(codes[j+2:j+5]); j+=4
                    j+=1
                i+=m.end(); continue
            m=re.match(r'\x1b\][^\x07]*\x07', line[i:])
            if m: i+=m.end(); continue
            i+=1; continue
        out.append((line[i], cur['fg'], cur['bg'], ','.join(sorted(cur['a']))))
        i+=1
    return out
for ln,line in enumerate(sys.stdin.read().split('\n')):
