import sys, re
class Cell:
    __slots__=('ch','fg','bg','at')
    def __init__(s): s.ch=' '; s.fg=''; s.bg=''; s.at=frozenset()
    def key(s): return (s.fg,s.bg,tuple(sorted(s.at)))
class VT:
    def __init__(s,w,h):
        s.w=w; s.h=h
        s.g=[[Cell() for _ in range(w)] for _ in range(h)]
        s.x=0; s.y=0; s.fg=''; s.bg=''; s.at=set(); s.wrap=True
    def put(s,ch):
        if s.x>=s.w:
            if s.wrap: s.x=0; s.y=min(s.y+1,s.h-1)
            else: s.x=s.w-1
        c=s.g[s.y][s.x]; c.ch=ch; c.fg=s.fg; c.bg=s.bg; c.at=frozenset(s.at); s.x+=1
    def sgr(s,params):
        if not params: params=[0]
        i=0
        while i<len(params):
            p=params[i]
            if p==0: s.fg=''; s.bg=''; s.at=set()
            elif p==1: s.at.add('bold')
            elif p==2: s.at.add('dim')
            elif p==3: s.at.add('italic')
            elif p==4: s.at.add('underlined')
            elif p==5: s.at.add('blink')
            elif p==7: s.at.add('inverted')
            elif p==9: s.at.add('strikethrough')
            elif p==22: s.at.discard('bold'); s.at.discard('dim')
            elif p==23: s.at.discard('italic')
            elif p==24: s.at.discard('underlined')
            elif p==25: s.at.discard('blink')
            elif p==27: s.at.discard('inverted')
            elif p==29: s.at.discard('strikethrough')
            elif 30<=p<=37 or 90<=p<=97: s.fg=str(p)
            elif p==39: s.fg=''
            elif 40<=p<=47 or 100<=p<=107: s.bg=str(p)
            elif p==49: s.bg=''
            elif p in (38,48):
                key='fg' if p==38 else 'bg'
                if i+1<len(params) and params[i+1]==5:
                    v='256:%d'%params[i+2]; i+=2
                elif i+1<len(params) and params[i+1]==2:
                    v='rgb:%d:%d:%d'%tuple(params[i+2:i+5]); i+=4
                else: v=''
                if key=='fg': s.fg=v
                else: s.bg=v
            i+=1
    def feed(s,data):
        i=0; n=len(data)
        while i<n:
            c=data[i]
            if c=='\x1b':
                m=re.match(r'\x1b\[([0-9;?]*)([A-Za-z])',data[i:])
                if m:
                    ps=m.group(1); fin=m.group(2)
                    priv = ps.startswith('?')
                    nums=[int(x) if x else 0 for x in ps.lstrip('?').split(';')] if ps.lstrip('?') else []
                    a=nums[0] if nums else 0
                    if fin=='m' and not priv: s.sgr(nums)
                    elif fin=='A': s.y=max(0,s.y-max(1,a))
                    elif fin=='B': s.y=min(s.h-1,s.y+max(1,a))
                    elif fin=='C': s.x=min(s.w-1,s.x+max(1,a))
                    elif fin=='D': s.x=max(0,s.x-max(1,a))
                    elif fin=='H' or fin=='f':
                        r=nums[0] if len(nums)>0 else 1; cc=nums[1] if len(nums)>1 else 1
                        s.y=max(0,min(s.h-1,r-1)); s.x=max(0,min(s.w-1,cc-1))
                    elif fin=='J':
                        if a==2:
                            for row in s.g:
                                for cl in row: cl.ch=' '; cl.fg=''; cl.bg=''; cl.at=frozenset()
                    elif fin=='K':
                        rng = range(s.x,s.w) if a==0 else (range(0,s.x+1) if a==1 else range(0,s.w))
                        for xx in rng:
                            cl=s.g[s.y][xx]; cl.ch=' '; cl.fg=''; cl.bg=''; cl.at=frozenset()
                    elif fin=='h' and priv:
                        if a==7: s.wrap=True
                    elif fin=='l' and priv:
                        if a==7: s.wrap=False
                    i+=m.end(); continue
                m=re.match(r'\x1bP.*?\x1b\\',data[i:],re.S)
                if m: i+=m.end(); continue
                m=re.match(r'\x1b\].*?(\x07|\x1b\\)',data[i:],re.S)
                if m: i+=m.end(); continue
                m=re.match(r'\x1b[=>()][0-9A-Za-z]?',data[i:])
                if m: i+=m.end(); continue
                i+=1; continue
            if c=='\r': s.x=0; i+=1; continue
            if c=='\n':
                s.y=min(s.h-1,s.y+1); i+=1; continue
            if c=='\x00' or c=='\x07': i+=1; continue
            if c=='\b': s.x=max(0,s.x-1); i+=1; continue
            s.put(c); i+=1
        return s
    def plain(s):
        return '\n'.join(''.join(c.ch for c in row).rstrip() for row in s.g)
    def styled(s):
        out=[]
        for yi,row in enumerate(s.g):
            runs=[]
            for c in row:
                k=c.key()
                if runs and runs[-1][0]==k: runs[-1][1]+=c.ch
                else: runs.append([k,c.ch])
            while runs and runs[-1][0]==('','',()) and runs[-1][1].strip()=='': runs.pop()
            out.append(f"{yi+1:3d}: "+" ".join(f"[{k[0]}|{k[1]}|{','.join(k[2])}]{t!r}" for k,t in runs))
        return '\n'.join(out)
if __name__=='__main__':
    w=int(sys.argv[1]); h=int(sys.argv[2]); mode=sys.argv[3] if len(sys.argv)>3 else 'plain'
    data=sys.stdin.buffer.read().decode('utf8',errors='replace')
    vt=VT(w,h); vt.feed(data)
    print(vt.plain() if mode=='plain' else vt.styled())
